  const scenario={id:uid("scenario"),title,mode:"structured",system:state.config.system,metadata:{era:"custom",eraLabel:"自定义",difficulty:"未标注",themes:["自定义导入"],estimatedMinutes:0,combatLevel:"未知",horrorLevel:"未知",recommendedOccupations:[],recommendedSkills:[],sourceType:"import"},chapters:[],rawText:raw,warnings:[]};let chapter=null,scene=null,node=null;const usedIds=new Set();
  function uniqueId(text,prefix){let id=makeSlug(text,prefix),i=2;while(usedIds.has(id))id=`${makeSlug(text,prefix)}-${i++}`;usedIds.add(id);return id}
  function ensureChapter(){if(!chapter){chapter={id:uniqueId("默认章节","chapter"),title:"默认章节",scenes:[]};scenario.chapters.push(chapter)}return chapter}
