function endingConditionMatches(ending,campaign=state.campaign,clues=state.clues){const flags=campaign.flags||{},outcomes={...defaultOutcomes(),...(campaign.outcomes||{})};if((ending.requiredFlags||[]).some(flag=>flags[flag]!==true))return false;if((ending.forbiddenFlags||[]).some(flag=>flags[flag]===true))return false;if(Number(ending.minClues||0)>clues.length)return false;if(Array.isArray(ending.requiresAnyClueIds)&&ending.requiresAnyClueIds.length&&!ending.requiresAnyClueIds.some(id=>clues.some(c=>c.id===id)))return false;if(isPlainObject(ending.outcomeRequirements))for(const [key,value] of Object.entries(ending.outcomeRequirements)){const allowed=Array.isArray(value)?value:[value];if(!allowed.includes(outcomes[key]))return false}return true}
function availableEndings(campaign=state.campaign,clues=state.clues){return (state.scenario?.endings||[]).filter(ending=>ending.alwaysAvailable||endingConditionMatches(ending,campaign,clues)).sort((a,b)=>Number(b.priority||0)-Number(a.priority||0))}
function validateEndingProposal(proposal,campaignView=state.campaign,cluesView=state.clues){if(!proposal)return null;if(!isPlainObject(proposal)||hasDangerousKeys(proposal))throw new Error("endingProposal 格式非法");const endingId=asString(proposal.endingId,120),ending=(state.scenario?.endings||[]).find(item=>item.id===endingId);if(!ending)throw new Error("提议的结局不存在");if(!ending.alwaysAvailable&&!endingConditionMatches(ending,campaignView,cluesView))throw new Error("当前状态尚未满足该结局条件");return{endingId,title:ending.playerTitle||ending.title,reason:asString(proposal.reason,500),ending:deepClone(ending)}}

function formatScenarioBriefing(scenario,{includeOpening=true,includeActions=true}={}){
  const b=scenario?.briefing;if(!b)return "";const sections=[];
  if(b.subtitle)sections.push(`【案件】${b.subtitle}`);
  if(b.era)sections.push(`【时间与地点】${b.era}`);
  if(b.playerRole)sections.push(`【你的身份】${b.playerRole}`);
  if(b.premise)sections.push(`【委托缘由】${b.premise}`);
  if(Array.isArray(b.knownFacts)&&b.knownFacts.length)sections.push(`【你已知的情况】\n${b.knownFacts.map((x,i)=>`${i+1}. ${x}`).join("\n")}`);
  const objectives=b.caseObjectives||[];if(objectives.length)sections.push(`【案件委托】\n${objectives.map((x,i)=>`${i+1}. ${x}`).join("\n")}`);
  if(includeOpening&&b.opening)sections.push(`【开场】${b.opening}`);
  if(includeActions&&Array.isArray(b.suggestedActions)&&b.suggestedActions.length)sections.push(`【行动参考】\n${b.suggestedActions.map((x,i)=>`${i+1}. ${x}`).join("\n")}`);
  return sections.join("\n\n");
}
