  const b=state.scenario.briefing||{};state.context.pinnedFacts=[b.playerRole?`玩家身份：${b.playerRole}`:"",...listStrings(b.caseObjectives,8,300).map(x=>`案件委托：${x}`),...listStrings(b.knownFacts,10,300).slice(0,3).map(x=>`开场已知事实：${x}`)].filter(Boolean);
  if(!state.saveMeta.slotName||state.saveMeta.slotName==="未命名调查"||state.saveMeta.slotName===previousScenarioTitle)state.saveMeta.slotName=scenario.title;setPhase(state.character?"awaiting_player_action":"scenario_ready",{force:true});bumpRevision();addLog("scenario",`启用剧本：${scenario.title}`);
